#!/usr/bin/env bash
# run_kvtest.sh — launch the mooncake_kvtest C++ binary for kvtest scenarios
# on the server (pod or bare-metal node).
#
# Usage: run_kvtest.sh LOG_FILE CONFIG_JSON [BINARY]
#   LOG_FILE    stdout/stderr of the binary (the full glog goes to
#               $MC_LOG_DIR/<prog>.*.INFO.* — see the export below)
#   CONFIG_JSON per-instance kvtest config generated by benchmark.py; the
#               __UB_DEVICE__ placeholder is late-bound here from
#               $SETUP_UB_DEVICE (env.sh probes it per pod via urma_admin)
#   BINARY      mooncake_kvtest path (default: mooncake_kvtest from PATH)
#
# Everything else (MC_* SDK vars, SETUP_*) comes from env.sh (sourced here),
# then env.mooncake.sh (hand-editable tuning panel; same-name vars win). The
# exit code is written to $LOG_FILE.exitrc so the orchestrator can fail the
# scenario when a backgrounded instance dies with an error.

set -u
SCRIPT_DIR="$(cd "$(dirname "$0")" && pwd)"
ENV_FILE="$SCRIPT_DIR/env.sh"

usage() { echo "usage: $0 LOG_FILE CONFIG_JSON [BINARY]" >&2; exit 2; }

[ $# -ge 2 ] || usage
LOG_FILE=$1
CONFIG=$2
BINARY=${3:-mooncake_kvtest}

if [ ! -f "$ENV_FILE" ]; then
  echo "[FATAL] env.sh not found in $SCRIPT_DIR" >&2
  exit 1
fi
source "$ENV_FILE"
# Hand-editable mooncake tuning defaults; sourced AFTER env.sh so same-name
# vars here override the generated env.sh (same rule as the other runners).
if [ -f "$SCRIPT_DIR/env.mooncake.sh" ]; then
  source "$SCRIPT_DIR/env.mooncake.sh" || exit 1
fi

# All logs for this instance belong in the hostPath-mounted per-pod directory
# (<host_log_root>/<run_id>/<pod>/ on the node). MC_LOG_DIR points at a
# per-process subdirectory: the SDK initializes glog from it (glog_compat), so
# the FULL glog (INFO/WARN/ERROR, rotated segments included) lands there — the
# report parses <MC_LOG_DIR>/*.INFO.* directly and does not rely on stderr.
# One subdirectory per process/size keeps rotated files and multi-size pod
# reuse from mixing. env.mooncake.sh may still override (sourced above).
export MC_LOG_DIR="${MC_LOG_DIR:-$(dirname "$LOG_FILE")/$(basename "$LOG_FILE" .log).glog.d}"
mkdir -p "$MC_LOG_DIR"

if [ ! -x "$(command -v "$BINARY" 2>/dev/null)" ] && [ ! -x "$BINARY" ]; then
  echo "[FATAL] mooncake_kvtest binary not found or not executable: $BINARY" >&2
  exit 1
fi

mkdir -p "$(dirname "$LOG_FILE")"

# Late-bind the per-process fabric address and UB device. In k8s POD_IP wins;
# in ssh mode SETUP_FABRIC_IP comes from the generated per-node env.sh.
FABRIC_IP=${POD_IP:-${SETUP_FABRIC_IP:-}}
if [ -z "$FABRIC_IP" ]; then
  echo "[FATAL] POD_IP/SETUP_FABRIC_IP is empty" >&2
  exit 1
fi
FINAL_CONFIG="$CONFIG.final.json"
fabric_escaped=${FABRIC_IP//&/\\&}
device_escaped=${SETUP_UB_DEVICE:-}
device_escaped=${device_escaped//&/\\&}
sed -e "s/__FABRIC_IP__/${fabric_escaped}/g" \
    -e "s/__UB_DEVICE__/${device_escaped}/g" \
    "$CONFIG" > "$FINAL_CONFIG"

# binary_local deployments place shared objects beside the binary under lib/.
RESOLVED_BINARY=$(command -v "$BINARY" 2>/dev/null || printf '%s' "$BINARY")
BINARY_DIR=$(cd "$(dirname "$RESOLVED_BINARY")" && pwd)
export LD_LIBRARY_PATH="${BINARY_DIR}/lib:${BINARY_DIR}/../lib:${LD_LIBRARY_PATH:-}"
if command -v ldd >/dev/null 2>&1; then
  missing_libs=$(ldd "$RESOLVED_BINARY" 2>/dev/null | awk '/not found/ {print}')
  if [ -n "$missing_libs" ]; then
    echo "[FATAL] mooncake_kvtest has missing shared libraries:" >&2
    echo "$missing_libs" >&2
    exit 1
  fi
fi

LAUNCH_CMD=()
if [ -n "${KVTEST_NUMA_NODE:-}" ]; then
  if ! [[ "$KVTEST_NUMA_NODE" =~ ^[0-9]+$ ]]; then
    echo "[FATAL] KVTEST_NUMA_NODE must be a non-negative integer: $KVTEST_NUMA_NODE" >&2
    exit 1
  fi
  if ! command -v numactl >/dev/null 2>&1; then
    echo "[FATAL] KVTEST_NUMA_NODE=$KVTEST_NUMA_NODE requires numactl in the container" >&2
    exit 1
  fi
  allowed_cpus=$(grep '^Cpus_allowed_list:' /proc/self/status 2>/dev/null | awk '{print $2}')
  allowed_mems=$(grep '^Mems_allowed_list:' /proc/self/status 2>/dev/null | awk '{print $2}')
  echo "[kvtest] NUMA bind node=$KVTEST_NUMA_NODE cgroup_cpus=${allowed_cpus:-unknown} cgroup_mems=${allowed_mems:-unknown}"
  LAUNCH_CMD=(numactl "--cpunodebind=$KVTEST_NUMA_NODE" "--membind=$KVTEST_NUMA_NODE")
fi

# stdout (kvtest narrative) + any stderr (fatal/non-glog output) share the
# narrative file: the full C++ glog now goes to MC_LOG_DIR/<prog>.*.INFO.*
# (glog_compat initialized glog from MC_LOG_DIR), so there is no separate
# $LOG_FILE.glog any more. ylt easylog stays beside them (same on-node 现场
# directory contract).
MC_YLT_LOG_PATH="$LOG_FILE.ylt.log" \
"${LAUNCH_CMD[@]}" "$BINARY" "$FINAL_CONFIG" \
  > "$LOG_FILE" 2>&1
rc=$?
# exit-code ledger: the orchestrator reads $LOG_FILE.exitrc after waiting
# for a backgrounded instance — a non-zero rc must FAIL the scenario
echo "$rc" > "$LOG_FILE.exitrc"
exit "$rc"
